// utils/soundEffects.js
// 🔊 Effet sonore bancaire signature ("Chime" Wave / Apple Pay)
//    - 100% Hors-ligne (embarqué en WAV PCM synthétisé haute fidélité)
//    - Zéro latence de téléchargement (0ms)
//    - Compatible iOS, Android et Web
import { Platform } from 'react-native';
import * as FileSystem from 'expo-file-system';
import { triggerSuccessHaptic } from './haptics';

export const SUCCESS_CHIME_BASE64 = "";


let cachedSoundUri = null;

/**
 * Prépare le fichier audio en cache local pour une lecture instantanée sans délai (0ms).
 */
async function getChimeUri() {
  if (cachedSoundUri) return cachedSoundUri;
  if (Platform.OS === 'web') {
    cachedSoundUri = 'data:audio/wav;base64,' + SUCCESS_CHIME_BASE64;
    return cachedSoundUri;
  }

  try {
    const fileUri = (FileSystem.cacheDirectory || '') + 'ntalbey_success_chime_v2.wav';
    const info = await FileSystem.getInfoAsync(fileUri);
    if (!info.exists) {
      await FileSystem.writeAsStringAsync(fileUri, SUCCESS_CHIME_BASE64, {
        encoding: FileSystem.EncodingType.Base64,
      });
    }
    cachedSoundUri = fileUri;
    return cachedSoundUri;
  } catch (err) {
    return 'data:audio/wav;base64,' + SUCCESS_CHIME_BASE64;
  }
}

// Pré-chargement silencieux en tâche de fond
getChimeUri().catch(() => {});

/**
 * Joue le carillon de succès bancaire ("Chime") avec vibration haptique.
 */
export async function playSuccessChime() {
  try {
    // 1. Déclenchement haptique de succès immédiat
    try {
      triggerSuccessHaptic();
    } catch (_) {}

    // 2. Web Audio
    if (Platform.OS === 'web' && typeof window !== 'undefined') {
      try {
        const audio = new Audio('data:audio/wav;base64,' + SUCCESS_CHIME_BASE64);
        audio.volume = 0.95;
        audio.play().catch(() => {});
        return;
      } catch (_) {}
    }

    // 3. React Native (iOS / Android via expo-audio)
    const uri = await getChimeUri();
    const { createAudioPlayer, setAudioModeAsync } = require('expo-audio');

    try {
      await setAudioModeAsync({
        playsInSilentMode: true,
      });
    } catch (_) {}

    const player = createAudioPlayer({ uri });
    player.play();

    // Nettoyage après 1.5s
    setTimeout(() => {
      try {
        if (typeof player.remove === 'function') player.remove();
      } catch (_) {}
    }, 1500);
  } catch (err) {
    if (__DEV__) console.log('Chime sound notice:', err?.message);
  }
}
